contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 1 ether);
        c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        require(balBefore >= amount);
        require(amount > 0);
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint myBalBefore = address(this).balance;
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        assert(c.depositsCount() == countBefore && address(c).balance == balBefore - amount && address(this).balance == myBalBefore + amount);
    }
    receive() external payable {}
}

