// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 1 ether);
        try c.depositsCount() {} catch { return; }
        uint balBefore = address(c).balance;
        vm.assume(balBefore >= amount);
        vm.assume(amount > 0);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint myBalBefore = address(this).balance;
        try c.withdraw(amount) {} catch { return; }
        assertTrue(c.depositsCount() == countBefore && address(c).balance == balBefore - amount && address(this).balance == myBalBefore + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
